def uv_charts(bm, uv):
    """Face islands connected by edges whose two faces share the same UVs (no seam)."""
    def joined(e):
        if len(e.link_faces) != 2:
            return False
        f1, f2 = e.link_faces
        for v in e.verts:
            u1 = next(l[uv].uv for l in f1.loops if l.vert == v)
            u2 = next(l[uv].uv for l in f2.loops if l.vert == v)
            if (u1 - u2).length > 1e-4:
                return False
        return True
    seen, out = set(), []
    for f in bm.faces:
        if f.index in seen:
            continue
        stack, comp = [f], []
        seen.add(f.index)
        while stack:
            a = stack.pop()
            comp.append(a.index)
            for e in a.edges:
                if joined(e):
                    for b in e.link_faces:
                        if b.index not in seen:
                            seen.add(b.index)
                            stack.append(b)
        out.append(comp)
    return out


