MEL = unreal.MaterialEditingLibrary
m = unreal.load_asset("/Game/HologramShader/Materials/HologramShader/M_Hologram")
for p in ("blend_mode", "shading_model", "two_sided", "translucency_lighting_mode", "used_with_static_lighting"):
    try:
        unreal.log("INSPECT %s = %s" % (p, m.get_editor_property(p)))
    except Exception as e:
        unreal.log("INSPECT %s ? %s" % (p, e))
