{
	inline const FName WaveFreq(TEXT("EntityTentacleWaveFreq"));             // Hz of the idle undulation
	inline const FName WaveAmp(TEXT("EntityTentacleWaveAmp"));               // degrees at the tip
	inline const FName WaveLength(TEXT("EntityTentacleWaveLength"));         // wave number, in bones
	inline const FName WaveFreqSpread(TEXT("EntityTentacleWaveFreqSpread")); // +- share of the frequency, per chain
	inline const FName WaveAmpSpread(TEXT("EntityTentacleWaveAmpSpread"));   // +- share of the amplitude, per chain
	inline const FName TipBias(TEXT("EntityTentacleTipBias"));               // 1 = linear growth to the tip; above 1 = more motion at the tip
	inline const FName FollowStiffness(TEXT("EntityTentacleFollowStiffness")); // 1/s^2: how hard a joint is pulled to the pose
